namespace Mustask.AppHost.Provisioning;

/// <summary>
/// Everything <see cref="KeycloakStandProvisioner"/> needs, gathered in one
/// place so the unit tests (`Mustask.Contracts.Tests`) construct it directly
/// instead of reaching into `AppHost.cs`'s top-level script. Every value here is either generated by
/// `Mustask.AppHost` itself or already known to it — nothing is read from a
/// human-set secret beyond the existing Keycloak admin password (no
/// fourth mandatory secret on a fresh clone).
/// </summary>
public sealed record KeycloakStandProvisioningOptions
{
    /// <summary>The only realm the stand provisioning touches (`Keycloak:Realm`, tech-024).</summary>
    public string Realm { get; init; } = KeycloakStandIdentifiers.DefaultRealm;

    /// <summary>Master-realm admin username — always `admin` on this stand (`AppHost.cs`).</summary>
    public required string AdminUsername { get; init; }

    /// <summary>Master-realm admin password — `Parameters:keycloak-admin-password`, already a mandatory secret.</summary>
    public required string AdminPassword { get; init; }

    /// <summary>Stand-only client's `clientId` — fixed: `mustask-e2e`.</summary>
    public required string ClientId { get; init; }

    /// <summary>Generated fresh by `Mustask.AppHost` at every stand start — never human-chosen.</summary>
    public required string ClientSecret { get; init; }

    /// <summary>Fixture user's username — fixed: `e2e-fixture`.</summary>
    public required string FixtureUsername { get; init; }

    /// <summary>
    /// The client roles of `mustask-api` the fixture user is given directly (tech-024, ADR-0033: the company realm allows
    /// no groups or realm roles of ours). `user` signs in; `system-admin` holds every instance right, so the fixture is the
    /// <b>instance</b> administrator as the group «Администраторы» made it before: it reads and writes the dictionaries and
    /// creates organizations, and becomes the administrator of each organization it creates. It holds no organization right of
    /// its own: a user it did not add to an organization sees nothing of it.
    /// </summary>
    public IReadOnlyList<string> FixtureRoles { get; init; } = KeycloakStandIdentifiers.FixtureRoles;

    /// <summary>
    /// The Docker name AppHost assigned the `keycloak` container
    /// (`AppHost.cs`, `.WithContainerName(...)`) — written to
    /// the stand file so the E2E suite's container resolver has an
    /// exact name instead of a prefix guess.
    /// </summary>
    public required string KeycloakContainerName { get; init; }

    /// <summary>The realm's issuer URL — the staleness guard in the stand file.</summary>
    public required string Issuer { get; init; }

    /// <summary>Absolute path of the stand file this provisioning writes (anchored, not cwd-relative).</summary>
    public required string StandFilePath { get; init; }

    /// <summary>
    /// Realm `mustask`'s `accessTokenLifespan`,
    /// set with the master-realm admin credentials this provisioner already
    /// holds — never by `mustask-e2e`, which stays without `manage-realm`. Fixed
    /// by `KeycloakStandIdentifiers.AccessTokenLifespanSeconds` (120); kept
    /// as its own option (not read from the constant inside this class)
    /// purely so the unit tests can exercise an arbitrary value without a
    /// compile-time dependency on that literal.
    /// </summary>
    public required int AccessTokenLifespanSeconds { get; init; }
}
